def count_hexagons_v6(n):
    ans = 0
    for a in range(-n, n + 1):
        for b in range(-n, n + 1):
            if a == 0 and b == 0:
                continue
            s2 = a*a + a*b + b*b
            if s2 > n*n:
                continue

            R_sum = min(n, n-a-b, n-2*a-b, n-2*a-2*b, n-a+b, n-a)
            L_sum = max(-n, -n-a-b, -n-2*a-b, -n-2*a-2*b, -n-a+b, -n-a)
            R_y0 = min(n, n-b, n-a-2*b, n-2*a-2*b, n-2*a-b, n-a)
            L_y0 = max(-n, -n-b, -n-a-2*b, -n-2*a-2*b, -n-2*a-b, -n-a)
            R_x0 = min(n, n-a, n-a+b, n+2*b, n+a+2*b, n+a+b)
            L_x0 = max(-n, -n-a, -n-a+b, -n+2*b, -n+a+2*b, -n+a+b)

            if L_x0 <= R_x0 and L_y0 <= R_y0 and L_sum <= R_sum:
                current_count = 0
                for k in range(L_sum, R_sum + 1):
                    low = max(L_x0, k - R_y0)
                    high = min(R_x0, k - L_y0)
                    if high >= low:
                        current_count += (high - low + 1)
                ans += current_count

    return ans // 12

for n in range(1, 5):
    print(f"n={n}: {count_hexagons_v6(n)}")

